static char *find_substring(const char *haystack, const char *needle) {
    if (haystack == NULL || needle == NULL) {
        return NULL;
    }
    if (!*needle) {
        return (char *)haystack;
    }
    size_t needle_len = strlen(needle);
    for (; *haystack; haystack++) {
        if (*haystack == *needle && strncmp(haystack, needle, needle_len) == 0) {
            return (char *)haystack;
        }
    }
    return NULL;
}

static void path_concat3(char *dst, size_t dst_max, const char *p1, const char *p2, const char *p3) {
    dst[0] = '\0';
    size_t cur = 0;
    const char *parts[3] = { p1, p2, p3 };
    for (int i = 0; i < 3; i++) {
        if (parts[i] == NULL) continue;
        size_t l = strlen(parts[i]);
        if (cur + l >= dst_max - 1) {
            l = dst_max - 1 - cur;
        }
        memcpy(dst + cur, parts[i], l);
        cur += l;
        dst[cur] = '\0';
    }
}

static void clean_token(char *dst, size_t dst_max, const char *src, size_t len) {
    size_t d = 0;
    for (size_t s = 0; s < len && d + 1 < dst_max; s++) {
        char c = src[s];
        if (c >= 'A' && c <= 'Z') {
            c = (char)(c - 'A' + 'a');
        }
        if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_') {
            dst[d++] = c;
        }
    }
    dst[d] = '\0';
}

